package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Ka Badbaadso Xumaanta Camalkayga", "Allahayow waxaan kaa magan galay xumaanta aan sameeyay iyo xumaanta aanan falin.", "Ducada Nabiga ﷺ, sida ay sheegtay Aisha (RA).", "In laga ilaaliyo cawaaqib xumada ka dhalan karta wixii la qabtay iyo waxa la iska daayo labadaba."),
        "dua_jahdil_bala" to DuaText("Ka Qaxooti Tijaabooyin Adag", "Illahow waxaan kaa magan galayaa fitno daran, in aad dhibta igu habsato, iyo in aad cadaw ku faanto.", "In laga cararo imtixaannada adag iyo faanidda cadawga.", "Nebigu ﷺ ayaa afartan shay ka magan galay."),
        "dua_fitnat_ghina_faqr" to DuaText("Ka Qaxoontiga Tijaabadaha Maalka iyo Saboolnimada", "Illahow waxaan kaa magan galay caajisnimo iyo gabow, danbi iyo deyn, fitnada iyo cadaabka qabriga, fitnada iyo cadaabka naarta, sharka fitnada xoolaha, iyo fitnada faqriga.", "Ka carar fitnada qabriga, naarta, maalka iyo faqriga (ducada qayb ka mid ah).", "Ducada Nabiga oo dhamaystiran ﷺ."),
        "dua_kufr_faqr" to DuaText("gaalnimo iyo faqri ka magan galo", "Allahayow waxaan kaa magan galay gaalnimo iyo faqri, waxaana kaa magan galay cadaabka qabriga. Adiga mooyee ilaah kale ma jiro.", "Saddex jeer subax iyo galabba.", "Abu Bakrah (RA) wuxuu maqlay nabiga ﷺ isagoo leh sidan."),
        "dua_sharri_sami" to DuaText("Ka Badbaadso Xumaanta Dareenkayga", "Allahayow waxaan kaa magan galay xumaanta maqalkayga, xumaanta araggayga, xumaanta carrabkayga, xumaanta qalbigayga iyo xumaanta rabitaankayga.", "Waxaa baray Shakal bin Xumayd (RA).", "Ducada si loo ilaaliyo addimada iyo nafta dembiga."),
        "dua_hadm_gharaq" to DuaText("Ka Badbaadinta Dhimashada Kediska ah iyo Shilalka", "Alloow waxaan kaa magan galay inaan ku dumiyo (daro), inaan meel sare ka soo dhaco, oo aan qarqiyo, gubasho iyo gabow ka noqdo; Shaydaanka oo i dhumiya wakhtiga dhimashada, iyo inaan dhinto anoo ka cararaya jidkaaga, iyo inaan dhinto.", "Ka carar shilalka iyo dhimashada xun.", "Ducada Nabiga ﷺ."),
        "dua_ju_khiyanah" to DuaText("Gaajada iyo Khiyaanada ka magan galo", "Alloow gaajo ayaan kaa magan galay, waa saxaabi xun, waxaana kaa magan galayaa khayaanada, waayo waa kalsooni xumo.", "Gaajo iyo khiyaamo ka magan galo.", "Ducada Nabiga ﷺ."),
        "dua_huda_tuqa" to DuaText("Hanuun, cibaado, dhawrsanaan iyo ku filnaan", "Allahayow waxaan ku waydiisanayaa hanuun, cibaado, dhawrsanaan iyo isku filnaansho.", "Ducada Nabiga oo kooban ﷺ.", "Afar nimcadood oo diinta iyo adduunyada sal u ah."),
        "dua_aslih_li_dini" to DuaText("I toosi Diintayda, Aduunyada iyo Aakhiraba", "Allahayow u toosi diintayda oo ah ilaalinta arrimahayga oo dhan; u hagaaji noloshayda adduunyo, ee ay ku jirto nolosheyda; oo toosi aakhiradayda aan u noqon doono. Noloshu ii kordhi wanaag kasta, Geeridana iiga yeel xumaan kasta.", "Dib u habaynta diinta, adduun iyo aakhiro- saddexdaba.", "Ducada Nabiga oo dhamaystiran ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Quluubtayada u rog adeecidaada", "Allow quluubta rogrog, quluubtayada u soo jeedi adeecidaada.", "Duco ah in qalbiga lagu adkeeyo addeecidda.", "Dadka quluubtoodu waxay u dhaxaysaa labada far ee Eebaha Raxmaan ah."),
        "dua_jannah_nar" to DuaText("Weydiinta Jannada, Naarta laga magan galo", "Allow janatul firdowsa ayaan ku waydiisanayaa naartana waan kaa magan galay.", "Tashahhud ka dib ama wakhti kasta.", "Nebigu ﷺ wuxuu yidhi: Ducadeennu sidoo kale waxay ku wareegsan tahay arrintan."),
        "dua_khayri_kullih" to DuaText("Wax kasta oo wanaagsan, had iyo jeer", "Allahayow waxaan ku waydiisanayaa wanaag oo dhan - mid dhaw iyo mid daahida, waxaan ogahay iyo waxaanan ogayn - waxaana kaa magan galayaa xumaan oo dhan - mid dhaw iyo mid daahsan, waxaan ogahay iyo waxaanan ogayn. Illahow waxaan ku waydiisanayaa Janno iyo wixii hadal iyo camal ii soo dhaweeya, waxaana kaa magan galayaa naarta iyo wixii hadal iyo camal ii soo dhawaada.", "Nabigu ﷺ baray ducadan dhamaystiran Aisha (RA) (qayb ducada ka mid ah).", "Duco soo ururisa wanaag kasta."),
        "dua_ihdini_saddidni" to DuaText("Igu Hanuuniyo Oo Igu Toos", "Allahayow i hanuuniyo oo jidka toosan igu wad.", "Nabigu ﷺ baray cali (RA).", "Ka fikir sida hanuunka lagu hagayo oo kale, Sadadna sida toosan fallaadhoda."),
        "dua_hubbaka" to DuaText("Waydiisan Jaceylka Alle", "Allahayow waxaan ku waydiisanayaa jacaylkaaga, jacaylka kuwa ku jecel iyo camalka jacaylkaaga ii keena. Allow jacaylkaaga iga dhig mid iga jecel naftayda, qoyskayga iyo biyaha qabow.", "Ducadii Daawuud (AS) ee laxidhiidha nabiga ﷺ.", "Jacaylka Alle waa hantida ugu weyn."),
        "dua_filal_khayrat" to DuaText("Wanaagga oo la sameeyo oo Xumaanta laga tago", "Allahayow waxaan kaa baryayaa inaad ii suuro galiso inaan sameeyo camal wanaagsan, xumaantana ka tago, masaakiintana aan jeclaado, iina danbi dhaaf oo ii naxariiso. 033-033 Markaad u Waddo Fidmo Qoom i Qabta idinkoon laydin Maxkamadayn. Waxaan ku waydiisanayaa jacaylkaaga, jacaylka kuwa ku jecel, iyo jacaylka camalka ee igu soo dhaweeya jacaylkaaga.", "Allaah baray ducadan nabiga ﷺ riyo.", "Nabigu ﷺ wuxuu yidhi: waa run ee baro oo baro."),
        "dua_bi_ilmikal_ghayb" to DuaText("Aan Noolaado Inta Noloshu Wanaagsantahay", "Illahow aqoontaada waxa maqan iyo awoodaada uu makhluuqa u leeyahay- i noolee inta aad ogtihiin in noloshu ay ii roon tahay, oo i qaado markaad ogaato in geeridu ii roon tahay. Illahow waxaan ku waydiisanayaa cabsidaada si gaar ah iyo meel fagaare ah, hadalka xaqa ah ee ku qanacsanaanta iyo xanaaqa, iyo dhexdhexaadnimada faqriga iyo xoolaha.", "Ducadii Cammaar bin Yaasir (RA) (qaybtii furitaanka).", "Nebigu ﷺ ayaa ducadan ku tukaday."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Allow adigaan ku waydiisanayaa mahad oo dhan adigaa iska leh; Ilaah kale ma jiro adiga mooyaane, adaa nimceeyay, ee abuuray samooyinka iyo dhulka. Lahaanshahaaga sharafta iyo karaamada, Adiga noolow, arsaaqeeye!", "Nebigu ﷺ wuxuu yidhi ninkani wuxuu ku ducaystay magaca Alle ee ugu wayn.", "Duco lagu sameeyay Magacan ayaa laga jawaabay."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Allow adigaan ku waydiisanayaa, waayo waxaan ka marag kacayaa in aad Alle tahay; Ilaah kale ma jiro adiga mooyee, Adigaa kalida ah, waxna dhalin, hana dhalin, wax la mid ahna ma jiro.", "Nebigu ﷺ waxa uu yidhi ninkani waxa uu Alle ku waydiiyey magaciisa ugu wayn.", "Marka la waydiiyo, wuxuu bixiyaa; markuu u yeedhay ayuu ku jawaabay."),
        "dua_thabbitni_hadiyan" to DuaText("Iga Dhig mid Adag, Hanuunsan iyo Tusaha", "Allow i sugo oo iga yeel mid hanuunsan oo hanuunsan.", "Nabigu ﷺ wuxuu ducadan u sameeyay Jariir (RA) (laftaadu waxaad dhahdaa 'thabbitni').", "Ducada asalka ah ee Jarir (RA) waxay isticmaashaa ereyada 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("I cafi oo aqbal towbadayda", "Eebow ii dambi dhaaf oo ka toobad keen. Ee adaa aqbal toobada Naxariista.", "Boqol jeer hal fadhi - ku dhaqanka Nabiga ﷺ.", "Saxaabadu waxay tiriyeen nabiga ﷺ isagoo leh boqol jeer hal fadhi."),
        "dua_rafiq_ala" to DuaText("Ducadii Qofka Dhimanaya", "Allahayow ii dambi dhaaf, ii naxariiso, iguna darso saxaabigii ugu sarreeyay.", "Ducadii ugu dambaysay ee Nabiga ﷺ - si uu qofka buka naftiisa u sheego.", "Nabigu ﷺ waxa uu sameeyay ducadan markii uu geeriyooday."),
        "dua_la_bas_tahur" to DuaText("U raaxaynta Buka: Nadiifinta", "Wax dhib ah ma leh; waa daahir (dambiyada) hadduu Eebbe idmo.", "Si loo raaxeeyo bukaanka marka la booqanayo.", "Nebigu ﷺ waxa uu sidaa yidhi mar uu booqday dadka buka."),
        "dua_talqeen" to DuaText("Talqiin ee dhimanaya", "Ma jiro qof xaq u leh in la caabudo Alle mooyee.", "Ku akhri kalimada agtiisa qof dhimanaya (haku qasbin inay dhahaan).", "Ruuxii eraygiisa u dambeeya ee ah ‘Laa’ilaha illallaah’ wuxuu gelayaa Jannada (Abuu Daawuud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Halkii Geeri laga Rajayn lahaa", "Alloow i noolee inta ay noloshu ii roon tahay, oo i qaado marka ay geeridu ii roonaato.", "Halkii aad geeri ku rajayn lahayd dhib.", "Nebigu ﷺ wuxuu reebay rajada dhimashada wuxuuna baray taas bedelkeeda."),
        "dua_for_one_i_cursed" to DuaText("Qof aan ku xumeeyo Erayada", "Allow qofkasta oo mu’min ah oo aan aflagaadeeyay ka yeel arrin kuugu dhawaansho maalinta qiyaame.", "Qof aad si xun ula hadashay adigoo xanaaqsan.", "Ducada Nabiga ﷺ."),
        "dua_praising_someone" to DuaText("Marka Qof la ammaanayo", "Waxaan u arkaa hebel iyo hebel sidaan oo kale ah, Allaahna waa xisaabiyee, qofna kuma dammaanad qaadin Eebbe hortiisa.", "Marka qof la ammaanayo, halkii aad buunbuunin lahayd.", "Nebigu ﷺ waxa uu baray hab-dhaqankan ammaanta ah."),
        "dua_being_praised" to DuaText("Marka lagugu amaano", "Allow ha igu xisaabin waxay ku hadlayaan, oo iga cafi waxay garan waayeen.", "Marka la maqlo is ammaanay - dhaqanka saxiib (RA).", "Hab la iskaga ilaaliyo isla waynida marka la amaano."),
        "dua_non_muslim_sneezes" to DuaText("Marka uu hindhiso qof aan Muslim ahayn", "Alle ha idin hanuuniyo, arrimihiinana ha hagaajiyo.", "Marka qof aan muslim ahayn uu hindhiso oo uu yiraahdo Alxamdulilaah.", "Yuhuuddu waxay ku hindhiseen Nebiga agtiisa ﷺ iyagoo rajaynaya inuu yidhaahdo Yarhamukallah, isna wuu odhan jiray."),
        "dua_reply_ahl_kitab_salam" to DuaText("Ujawaab salaan Ehlu-kitaabka", "adigana.", "Marka Ehlu-kitaabku salaamo.", "Dardaarankii nabiga ﷺ."),
        "dua_fasting_invited" to DuaText("Marka Soonka Lagu Casuumo", "waan soomanahay", "Markaad sooman tahay lagu casuumo, ama marka qof kula murmo.", "Haddii qofka sooman uu martiqaad ka aqbalo, waa inuu u duceeyaa martigeliyaha."),
        "dua_for_who_gave_drink" to DuaText("Qofkii I Quudiya", "Allahayow quudi kii i quudiyay, kana waraabi kii i waraabiyay.", "Ku alla kii ku siiya cunto iyo cabitaan.", "Nabiga ﷺ wuxuu ducadan u sameeyay al-Miqdaad (RA)."),
        "dua_eid_greeting" to DuaText("Salaan Ciida", "Annaga iyo idinkaba Alle ha naga aqbalo", "Midba midka kale maalinta Ciidda - dhaqankii saxaabada sharafta leh (RA).", "Saxaabadu sidaas bay yiraahdeen markii ay ciidaha kulmeen."),
        "dua_wedding_night" to DuaText("Arooska Ka Dib Nikah", "Allahayow waxaan ku waydiisanayaa wanaageeda iyo wanaaga dabeecada aad ku abuurtay, waxaana kaa magan galayaa sharkeeda iyo xumaanta dabeecadda aad ku abuurtay.", "Nikaha ka dib, oo gacanta saaraya wejiga xaaska.", "Nabiga ﷺ waxbaridda - barakada guurka."),
        "dua_istisqa_ibadak" to DuaText("Waraabiyo Addoomadaada iyo Xoolahaaga", "Alloow addoommadaada iyo xoolahaaga ka waraabi, naxariistaadana sii faafi, dhulkaaga dhintayna noole noolee.", "Weydiinta roobka (istisqa).", "Nabigu ﷺ waxa uu sameeyay ducadan roobka."),
        "dua_seeing_clouds" to DuaText("Daruuro Madaw oo la arkayo", "Allow xumaanteeda waan kaa magan galay.", "Markaan arkay daruuro madow oo cirka; haduu da'o dheh Allahumma sayyiban naafica.", "Markuu arkay daruuraha, Nebigu ﷺ wuu ka tagi lahaa wuxuu samaynayo oo wuxuu samayn lahaa ducadan."),
        "dua_jamarat" to DuaText("Dhagxaan Jamarat", "Allaah ayaa u weyn.", "Dhagax kasta oo la tuuray.", "Nabigu ﷺ waxa uu yidhi takbiir quruurux kasta, dabadeed jamrahdii kowaad iyo labaad ka dib waxa ay wajahday qiblada oo duco dheer"),
        "dua_rabbi_ainni" to DuaText("Eebow Igu Gargaar oo Ha Iga Hortagin", "Eebbow i caawi oo ha ii gargaarin cid kale, i sii libinta oo ha igu libin cid kale, ii qorshee oo ha igu fikirin, i hanuunin oo ii fududee, igana gargaar ciddii i dulmiya.", "Ducada Nabiga oo dhamaystiran ﷺ (qayb furitaan).", "Duco ururisa caawimo kasta oo diin iyo adduunba ah."),
        "dua_ati_nafsi_taqwaha" to DuaText("Nafteyda Taqwadeeda Sii", "Allow naftayda sii cibaadadeeda oo nadiifi, adigaa ugu khayr badan oo daahiriya. Waxaad tahay ilaaliyeheeda iyo Sayidkeeda.", "Dib u habaynta iyo nadiifinta nafta.", "Nabigu ﷺ ayaa ducadan samayn jiray."),
        "dua_iqsim_lana_khashyatik" to DuaText("Cabsidan oo kale na sii", "Allahayow na sii cabsidaada oo nagu filan si aad noo dhex gasho iyo in aan ku caasiyo, adeecina noogu filan Jannadaada, iyo yaqiinsanaan nagu filan si aad noogu fududayso masiibooyinka aduunka. Aan ku raaxaysanno maqalkeena, arageena iyo xooggayaga inta aad noolashay, oo aad naga dhigayso kuwa naga dheereeya. Ka aargoosada kuwa na dulmiya, cadowgayaga nooga gargaara, yeynaan balaayadayadu diinteenna ku dhex jirin, adduunyadana ha ka dhigin wax na quseeya ama xadka cilmigeenna, hana naga dul-qaadin cid aan noo naxariisan.", "Markaad ka soo kacdo isu imaatinka - Nabiga ﷺ marar dhif ah ayuu u kacay isagoon samayn ducadan.", "Duco dhameestiran oo diinta, adduun iyo aakhiraba u wanaagsan."),
        "dua_infani_bima_allamtani" to DuaText("Ka Faa'iidayso Waxaad I Bartay", "Allahayow waxaad i bartay igu anfaca, I bar waxa anfacaya, cilmina ii kordhi.", "Markaad aqoon raadinayso ama ka hor intaanad wax baran.", "Duco aqoon faa'iido leh oo lagu dhaqmo."),
    )
}
